using System;using System.Reflection;using NUnit.Framework;
namespace LWS.TruckDentist.Tests {
 public sealed class DentalRulesTests {
  Type t,tool;object r;const BindingFlags Any=BindingFlags.Instance|BindingFlags.Public|BindingFlags.NonPublic;object Call(string n,params object[] a)=>t.GetMethod(n).Invoke(r,a);T Get<T>(string n)=>t.GetField(n,Any)!=null?(T)t.GetField(n,Any).GetValue(r):(T)t.GetProperty(n).GetValue(r);void Tick(float seconds){for(int i=0;i<Math.Ceiling(seconds/.05f);i++)Call("Tick",.05f);}int Contact(int id,int kind,int slot=0,float dt=.05f,float speed=.2f,float force=10)=>(int)Call("Contact",Get<int>("Round"),id,slot,Enum.ToObject(tool,kind),dt,speed,force);void Step(int id,int kind,int slot=0){int before=Get<int[]>("stage")[id];for(int i=0;i<45&&Get<int[]>("stage")[id]==before;i++)Contact(id,kind,slot);}void Dirty(int slot=0){int id=slot*4;Step(id,4,slot);Step(id,0,slot);Step(id,5,slot);Step(id,3,slot);}void Cavity(int slot=0){int id=slot*4+1;Step(id,4,slot);Step(id,1,slot);Step(id,4,slot);Step(id,5,slot);Step(id,3,slot);}
  [SetUp]public void Reset(){t=Type.GetType("LWS.TruckDentist.DentalRules, Assembly-CSharp",true);tool=t.Assembly.GetType("LWS.TruckDentist.DentalToolKind",true);r=Activator.CreateInstance(t);Call("Reset",4,3);}
  [Test]public void CountdownAndNonfiniteWorkDoNotAward(){Assert.That(Contact(0,4),Is.Zero);Tick(3.1f);Assert.That(Contact(0,4,dt:float.NaN),Is.Zero);Assert.That(Contact(0,4,speed:float.NaN),Is.Zero);Assert.That(Contact(0,4,force:float.PositiveInfinity),Is.Zero);Assert.That(Get<int[]>("points"),Is.All.Zero);}
  [Test]public void DirtyToothNeedsActualRinseBrushCleanDrySequence(){Tick(3.1f);Step(0,0);Assert.That(Get<int[]>("stage")[0],Is.Zero);Dirty();Assert.That(Get<bool[]>("done")[0],Is.True);Assert.That(Get<int[]>("procedures")[0],Is.EqualTo(1));Assert.That(Get<int[]>("points")[0],Is.EqualTo(80));}
  [Test]public void CavityNeedsDrillRerinseFillingAndDry(){Tick(3.1f);Cavity();Assert.That(Get<bool[]>("done")[1],Is.True);Assert.That(Get<int[]>("points")[0],Is.EqualTo(100));}
  [Test]public void AirAndWaterDoNotDamageHealthyTeeth(){Tick(3.1f);Step(3,4);Step(3,3);Assert.That(Get<int[]>("points"),Is.All.Zero);Assert.That(Get<int[]>("mistakes"),Is.All.Zero);Assert.That(Get<bool[]>("done")[3],Is.False);}
  [Test]public void DangerousToolOnHealthyToothCostsActualOwnerOncePerCooldown(){Tick(3.1f);Assert.That(Contact(3,1),Is.EqualTo(-20));for(int i=0;i<20;i++)Contact(3,1);Assert.That(Get<int[]>("mistakes")[0],Is.EqualTo(1));Tick(1.1f);Assert.That(Contact(3,1),Is.EqualTo(-20));}
  [Test]public void HighSpeedAndExcessiveNativeForcePenalizeInsteadOfProgress(){Tick(3.1f);Assert.That(Contact(0,4,speed:3),Is.EqualTo(-15));Tick(1.1f);Assert.That(Contact(0,4,force:18001),Is.EqualTo(-15));Assert.That(Get<int[]>("stage")[0],Is.Zero);}
  [Test]public void ExtractionCannotBeAwardedByContactTimerOrWrongTool(){Tick(3.1f);Step(2,4);Step(2,2);Assert.That(Get<bool[]>("done")[2],Is.False);Assert.That((int)Call("SocketBroke",0,2,0,false),Is.EqualTo(-60));Assert.That(Get<int[]>("procedures")[0],Is.Zero);}
  [Test]public void ActualCorrectRinsedSocketBreakAwardsExactlyOnce(){Tick(3.1f);Step(2,4);Assert.That((int)Call("SocketBroke",0,2,0,true),Is.EqualTo(90));Assert.That((int)Call("SocketBroke",0,2,0,true),Is.Zero);Assert.That(Get<int[]>("points")[0],Is.EqualTo(100));Assert.That(Get<int[]>("procedures")[0],Is.EqualTo(1));}
  [Test]public void WrongHealthyExtractionCannotBecomeCorrectProcedure(){Tick(3.1f);Assert.That((int)Call("SocketBroke",0,3,0,true),Is.EqualTo(-60));Assert.That(Get<int[]>("procedures")[0],Is.Zero);Assert.That(Get<bool[]>("broken")[3],Is.True);}
  [Test]public void OtherOwnersTargetAndStaleRoundsCannotAward(){Tick(3.1f);Assert.That(Contact(4,1),Is.EqualTo(-20));Assert.That((int)Call("SocketBroke",-1,2,0,true),Is.Zero);Assert.That(Get<int[]>("points")[1],Is.Zero);Assert.That(Get<int[]>("stage")[4],Is.Zero);}
  [Test]public void CompletedProcedureDoesNotBankAgain(){Tick(3.1f);Dirty();int points=Get<int[]>("points")[0];Step(0,3);Step(0,4);Assert.That(Get<int[]>("points")[0],Is.EqualTo(points));}
  [Test]public void AllActualProceduresAdvanceRoundAndRetainTotals(){Call("Reset",1,2);Tick(3.1f);Dirty();Cavity();Step(2,4);Call("SocketBroke",0,2,0,true);Tick(4.2f);Assert.That(Get<int>("Round"),Is.EqualTo(1));Assert.That(Get<int[]>("points")[0],Is.EqualTo(280));Assert.That(Get<int[]>("stage"),Is.All.Zero);Assert.That(Get<bool>("Complete"),Is.False);}
  [Test]public void FiniteRoundTimeoutAndRematchResetAllState(){Call("Reset",1,1);Tick(185);Assert.That(Get<bool>("Complete"),Is.True);Call("Reset",4,3);Assert.That(Get<int[]>("points"),Is.All.Zero);Assert.That(Get<int[]>("mistakes"),Is.All.Zero);Assert.That(Get<int>("Round"),Is.Zero);Assert.That(Get<bool>("Complete"),Is.False);}
  [Test]public void GenuineTiesUseOriginalActualScores(){Tick(3.1f);Dirty(0);Dirty(1);Assert.That((int)Call("Place",0),Is.EqualTo(1));Assert.That((int)Call("Place",1),Is.EqualTo(1));Assert.That((int)Call("Place",2),Is.EqualTo(3));}
 }
}
